// ============================================================
//  Render engine - called by each page via: renderPage('slug')
// ============================================================

function renderPage(slug) {
  const data = allData[slug];
  if (!data) return;
  const container = document.getElementById("productList");
  if (!container) return;
  container.innerHTML = "";
  data.products.forEach(p => {
    const tagsHTML = data.tags.map(t => `<span>${t}</span>`).join("");
    container.innerHTML += `
      <div class="product-card">
        <img src="${p.image}" alt="${p.name}" onerror="this.src='https://picsum.photos/800/500'">
        <div class="product-info">
          <h3>${p.name}</h3>
          <p>Professional tools with advanced features, responsive design and premium support.</p>
          <div class="tags">${tagsHTML}</div>
        </div>
        <div class="product-right">
          <div class="rating">${p.rating}</div>
          <button class="preview-btn" onclick="alert('Opening Live Preview for: ' + '${p.name.replace(/'/g,'&#39;')}')">Live Preview</button>
        </div>
      </div>`;
  });
}

document.querySelectorAll(".mobile-drop > span")
.forEach(item=>{

 item.addEventListener("click",()=>{

   const sub=item.nextElementSibling;

   sub.style.display=
   sub.style.display==="block"
   ?"none"
   :"block";

 });

});

// Search function used by all product pages
function searchProducts() {
  const input = document.getElementById("searchInput");
  if (!input) return;
  const val = input.value.toLowerCase();
  document.querySelectorAll(".product-card").forEach(card => {
    const h3 = card.querySelector("h3");
    card.style.display = h3 && h3.innerText.toLowerCase().includes(val) ? "flex" : "none";
  });
}

// Mobile menu toggle
function openMenu() {
  const m = document.getElementById("mobileMenu");
  if (m) m.style.left = "0";
}
function closeMenu() {
  const m = document.getElementById("mobileMenu");
  if (m) m.style.left = "-100%";
}

// Signup form handler
function goHome(e) {
  e.preventDefault();
  showPage('home');
}
